def transform(grid):
    h, w = len(grid), len(grid[0])
    color = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    full_rows = {r for r in range(h) if all(v == color for v in grid[r])}
    full_cols = {c for c in range(w) if all(grid[r][c] == color for r in range(h))}
    return [[2 if grid[r][c] == color and (r in full_rows or c in full_cols) else grid[r][c] for c in range(w)] for r in range(h)]
